        if (row, col) == goal:
            path.append((row, col))
            return True

        visited.add((row, col))
        path.append((row, col))

        # Explore neighbors
        neighbors = [(row + 1, col), (row - 1, col), (row, col + 1), (row, col - 1)]
        for nr, nc in neighbors:
            if is_valid(nr, nc) and dfs(nr, nc):
                return True

        path.pop()  # Backtrack
        return False

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if dfs(start[0], start[1]):
        return path
    else:
        return []
